<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal();$pdo=db();$pageTitle='Clientes';$q=trim($_GET['q']??'');$st=$pdo->prepare('SELECT * FROM clientes WHERE nome LIKE ? OR login LIKE ? OR cpf_cnpj LIKE ? OR email LIKE ? ORDER BY ativo DESC,nome');$x="%$q%";$st->execute([$x,$x,$x,$x]);$rows=$st->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$pdo->prepare('UPDATE clientes SET ativo=CASE ativo WHEN 1 THEN 0 ELSE 1 END, atualizado_em=? WHERE id=?')->execute([now(),$id]);log_action('ativação/desativação','clientes',$id);flash('success','Status do cliente atualizado.');redirect('index.php');}include __DIR__.'/../../includes/header.php'; ?><div class="page-head"><div><h1>Clientes</h1></div><a class="btn primary" href="form.php">＋ Novo cliente</a></div><div class="card"><form class="search-row"><input name="q" value="<?=e($q)?>" placeholder="Nome, CPF/CNPJ, login ou e-mail"><button class="btn secondary">Pesquisar</button></form></div><div class="card" style="margin-top:16px"><div class="table-wrap"><table class="table"><thead><tr><th>Nome</th><th>CPF/CNPJ</th><th>Contato</th><th>Login</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['nome'])?></td><td><?=e($r['cpf_cnpj'])?></td><td><?=e($r['telefone'])?><br><?=e($r['email'])?></td><td><?=e($r['login'])?></td><td><?=status_badge($r['ativo']?'Ativo':'Inativo')?></td><td class="nowrap"><a class="btn small secondary" href="form.php?id=<?=$r['id']?>">Editar</a> <form style="display:inline" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small secondary"><?=$r['ativo']?'Desativar':'Ativar'?></button></form></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="6" class="empty">Nenhum cliente encontrado.</td></tr><?php endif;?></tbody></table></div></div><?php include __DIR__.'/../../includes/footer.php'; ?>
